from typing import AsyncGenerator, Dict, Any
from repoforge.providers.base import BaseProvider


class MockProvider(BaseProvider):
    def _initialize(self):
        pass

    def generate(self, prompt: str, system_prompt: str = "", **kwargs) -> str:
        # Return a valid JSON action array so the ActionParser can read it
        return f"""
        [
            {{
                "type": "modify",
                "file": "mock_output.txt",
                "content": "This is a test file generated by RepoForge Mock Provider.\\nPrompt received: {prompt}"
            }}
        ]
        """

    async def stream(
        self,
        prompt: str,
        system_prompt: str = "",
        **kwargs
    ) -> AsyncGenerator[str, None]:
        yield self.generate(prompt, system_prompt, **kwargs)

    def get_capabilities(self) -> Dict[str, Any]:
        return {
            "chat": True,
            "stream": True,
            "vision": False,
            "tools": False,
        }

    @property
    def name(self) -> str:
        return "MockProvider"

    @property
    def models(self) -> list:
        return ["mock-v1"]
